ALTER TABLE public.profiles ADD COLUMN username text, ADD COLUMN bio text NOT NULL DEFAULT '', ADD COLUMN top_five jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE UNIQUE INDEX profiles_username_unique ON public.profiles(lower(username)) WHERE username IS NOT NULL;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_username_format CHECK (username IS NULL OR username ~ '^[a-zA-Z0-9_]{3,24}$'), ADD CONSTRAINT profiles_top_five_limit CHECK (jsonb_typeof(top_five) = 'array' AND jsonb_array_length(top_five) <= 5), ADD CONSTRAINT profiles_bio_limit CHECK (char_length(bio) <= 280);
ALTER TABLE public.lists ADD COLUMN visibility text NOT NULL DEFAULT 'private' CHECK (visibility IN ('private','friends','public'));
ALTER TABLE public.list_items ADD COLUMN genres text[] NOT NULL DEFAULT '{}';
CREATE TABLE public.friendships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, receiver_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted')), created_at timestamptz NOT NULL DEFAULT now(), CHECK (sender_id <> receiver_id));
GRANT SELECT, INSERT, DELETE ON public.friendships TO authenticated;
GRANT ALL ON public.friendships TO service_role;
ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX friendship_pair ON public.friendships(least(sender_id,receiver_id),greatest(sender_id,receiver_id));
CREATE POLICY friendship_read ON public.friendships FOR SELECT TO authenticated USING (auth.uid() IN (sender_id,receiver_id));
CREATE POLICY friendship_request ON public.friendships FOR INSERT TO authenticated WITH CHECK (sender_id=auth.uid() AND status='pending');
CREATE POLICY friendship_remove ON public.friendships FOR DELETE TO authenticated USING (auth.uid() IN (sender_id,receiver_id));
CREATE FUNCTION public.are_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.friendships WHERE status='accepted' AND ((sender_id=a AND receiver_id=b) OR (sender_id=b AND receiver_id=a))) $$;
REVOKE ALL ON FUNCTION public.are_friends(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.are_friends(uuid,uuid) TO authenticated,anon;
CREATE FUNCTION public.accept_friend(request_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.friendships SET status='accepted' WHERE id=request_id AND receiver_id=auth.uid() AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no disponible'; END IF; END $$;
REVOKE ALL ON FUNCTION public.accept_friend(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.accept_friend(uuid) TO authenticated;
CREATE FUNCTION public.can_read_list(lid uuid, uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.lists l WHERE l.id=lid AND (l.visibility='public' OR l.owner_id=uid OR public.is_list_member(lid,uid) OR (l.visibility='friends' AND public.are_friends(l.owner_id,uid)))) $$;
REVOKE ALL ON FUNCTION public.can_read_list(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_read_list(uuid,uuid) TO authenticated,anon;
GRANT SELECT ON public.lists,public.list_items,public.ratings,public.comments TO anon;
CREATE POLICY visibility_read_lists ON public.lists FOR SELECT TO authenticated,anon USING (public.can_read_list(id,auth.uid()));
CREATE POLICY visibility_read_items ON public.list_items FOR SELECT TO authenticated,anon USING (public.can_read_list(list_id,auth.uid()));
CREATE POLICY visibility_read_ratings ON public.ratings FOR SELECT TO authenticated,anon USING (public.can_read_list(list_id,auth.uid()));
CREATE POLICY visibility_read_comments ON public.comments FOR SELECT TO authenticated,anon USING (public.can_read_list(list_id,auth.uid()));
CREATE FUNCTION public.invite_friend(lid uuid,friend_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_list_member(lid,auth.uid()) OR NOT public.are_friends(auth.uid(),friend_id) THEN RAISE EXCEPTION 'No podés invitar a esta persona'; END IF; INSERT INTO public.list_members(list_id,user_id,role) VALUES(lid,friend_id,'collaborator') ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.invite_friend(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.invite_friend(uuid,uuid) TO authenticated;
CREATE TABLE public.watched_movies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, source text NOT NULL, external_id text NOT NULL, title text NOT NULL, year integer, image_url text, genres text[] NOT NULL DEFAULT '{}', score_10 smallint CHECK (score_10 BETWEEN 1 AND 10), review text NOT NULL DEFAULT '', watched_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,source,external_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.watched_movies TO authenticated;
GRANT ALL ON public.watched_movies TO service_role;
ALTER TABLE public.watched_movies ENABLE ROW LEVEL SECURITY;
CREATE POLICY watches_read ON public.watched_movies FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.are_friends(user_id,auth.uid()));
CREATE POLICY watches_write ON public.watched_movies FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('watched','rated','reviewed','created_list','added','commented')), list_id uuid REFERENCES public.lists(id) ON DELETE CASCADE, item_id uuid REFERENCES public.list_items(id) ON DELETE CASCADE, source text, external_id text, title text NOT NULL, image_url text, score_10 smallint, body text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity TO authenticated;
GRANT ALL ON public.activity TO service_role;
ALTER TABLE public.activity ENABLE ROW LEVEL SECURITY;
CREATE INDEX activity_cursor ON public.activity(created_at DESC,id DESC);
CREATE POLICY activity_read ON public.activity FOR SELECT TO authenticated USING ((user_id=auth.uid() OR public.are_friends(user_id,auth.uid())) AND (list_id IS NULL OR public.can_read_list(list_id,auth.uid())));
CREATE TABLE public.activity_likes (activity_id uuid NOT NULL REFERENCES public.activity(id) ON DELETE CASCADE,user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(activity_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.activity_likes TO authenticated;
GRANT ALL ON public.activity_likes TO service_role;
ALTER TABLE public.activity_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY likes_read ON public.activity_likes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.activity a WHERE a.id=activity_id));
CREATE POLICY likes_add ON public.activity_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.activity a WHERE a.id=activity_id));
CREATE POLICY likes_remove ON public.activity_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.social_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE,activity_id uuid REFERENCES public.activity(id) ON DELETE CASCADE,profile_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,list_id uuid REFERENCES public.lists(id) ON DELETE CASCADE,review_item_id uuid REFERENCES public.list_items(id) ON DELETE CASCADE,review_user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(activity_id,profile_id,list_id)=1),CHECK(review_item_id IS NULL OR (list_id IS NOT NULL AND review_user_id IS NOT NULL)));
GRANT SELECT,INSERT,DELETE ON public.social_comments TO authenticated;
GRANT ALL ON public.social_comments TO service_role;
ALTER TABLE public.social_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY social_comments_read ON public.social_comments FOR SELECT TO authenticated USING ((activity_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.activity a WHERE a.id=activity_id)) OR (profile_id IS NOT NULL AND (profile_id=auth.uid() OR public.are_friends(profile_id,auth.uid()))) OR (list_id IS NOT NULL AND public.can_read_list(list_id,auth.uid())));
CREATE POLICY social_comments_add ON public.social_comments FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND ((activity_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.activity a WHERE a.id=activity_id)) OR (profile_id IS NOT NULL AND public.are_friends(profile_id,auth.uid())) OR (list_id IS NOT NULL AND public.is_list_member(list_id,auth.uid()))));
CREATE POLICY social_comments_remove ON public.social_comments FOR DELETE TO authenticated USING(user_id=auth.uid() OR profile_id=auth.uid() OR public.is_list_owner(list_id,auth.uid()));
CREATE FUNCTION public.record_social_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.list_items; BEGIN
IF TG_TABLE_NAME='lists' THEN INSERT INTO public.activity(user_id,kind,list_id,title) VALUES(NEW.owner_id,'created_list',NEW.id,NEW.name);
ELSIF TG_TABLE_NAME='list_items' THEN INSERT INTO public.activity(user_id,kind,list_id,item_id,source,external_id,title,image_url) VALUES(NEW.added_by,'added',NEW.list_id,NEW.id,NEW.source,NEW.external_id,NEW.title,NEW.image_url);
ELSIF TG_TABLE_NAME='ratings' THEN SELECT * INTO i FROM public.list_items WHERE id=NEW.item_id; IF TG_OP='UPDATE' AND NEW.score_10 IS NOT DISTINCT FROM OLD.score_10 AND NEW.review IS NOT DISTINCT FROM OLD.review THEN RETURN NEW; END IF; INSERT INTO public.activity(user_id,kind,list_id,item_id,source,external_id,title,image_url,score_10,body) VALUES(NEW.user_id,CASE WHEN NEW.review<>'' THEN 'reviewed' ELSE 'rated' END,NEW.list_id,NEW.item_id,i.source,i.external_id,i.title,i.image_url,NEW.score_10,NEW.review);
ELSIF TG_TABLE_NAME='comments' THEN SELECT * INTO i FROM public.list_items WHERE id=NEW.item_id; INSERT INTO public.activity(user_id,kind,list_id,item_id,source,external_id,title,image_url,body) VALUES(NEW.user_id,'commented',NEW.list_id,NEW.item_id,i.source,i.external_id,i.title,i.image_url,NEW.body);
ELSIF TG_TABLE_NAME='watched_movies' THEN IF TG_OP='UPDATE' AND NEW.score_10 IS NOT DISTINCT FROM OLD.score_10 AND NEW.review IS NOT DISTINCT FROM OLD.review THEN RETURN NEW; END IF; INSERT INTO public.activity(user_id,kind,source,external_id,title,image_url,score_10,body) VALUES(NEW.user_id,CASE WHEN TG_OP='INSERT' THEN 'watched' WHEN NEW.review<>'' THEN 'reviewed' ELSE 'rated' END,NEW.source,NEW.external_id,NEW.title,NEW.image_url,NEW.score_10,NEW.review);
ELSIF TG_TABLE_NAME='social_comments' AND NEW.list_id IS NOT NULL THEN INSERT INTO public.activity(user_id,kind,list_id,title,body) SELECT NEW.user_id,'commented',NEW.list_id,name,NEW.body FROM public.lists WHERE id=NEW.list_id;
END IF; RETURN NEW; END $$;
CREATE TRIGGER social_list_created AFTER INSERT ON public.lists FOR EACH ROW EXECUTE FUNCTION public.record_social_activity();
CREATE TRIGGER social_item_added AFTER INSERT ON public.list_items FOR EACH ROW EXECUTE FUNCTION public.record_social_activity();
CREATE TRIGGER social_rating AFTER INSERT OR UPDATE ON public.ratings FOR EACH ROW EXECUTE FUNCTION public.record_social_activity();
CREATE TRIGGER social_comment AFTER INSERT ON public.comments FOR EACH ROW EXECUTE FUNCTION public.record_social_activity();
CREATE TRIGGER social_watch AFTER INSERT OR UPDATE ON public.watched_movies FOR EACH ROW EXECUTE FUNCTION public.record_social_activity();
CREATE TRIGGER social_list_comment AFTER INSERT ON public.social_comments FOR EACH ROW EXECUTE FUNCTION public.record_social_activity();